:root {
  --brand: #ff6b35;
  --brand-dark: #e85a26;
  --brand-soft: #fff1ea;
  --gold: #f5a623;
  --ink: #2d2320;
  --ink-2: #6b5f5a;
  --ink-3: #9b8f8a;
  --line: #f0e7e1;
  --bg: #fdf8f4;
  --card: #ffffff;
  --green: #2e9e6b;
  --red: #e04b3a;
  --radius: 16px;
  --shadow: 0 6px 24px rgba(190, 110, 60, 0.1);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'PingFang SC', 'Hiragino Sans GB',
    'Microsoft YaHei', sans-serif;
  background: var(--bg);
  color: var(--ink);
  font-size: 15px;
  line-height: 1.6;
}

a {
  color: var(--brand);
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  outline: none;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 9px 18px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 600;
  transition: transform 0.12s ease, opacity 0.12s ease, background 0.12s ease;
}
.btn:active {
  transform: scale(0.96);
}
.btn-primary {
  background: var(--brand);
  color: #fff;
}
.btn-primary:hover {
  background: var(--brand-dark);
}
.btn-primary:disabled {
  background: #f4c4b0;
  cursor: not-allowed;
}
.btn-ghost {
  background: var(--brand-soft);
  color: var(--brand);
}
.btn-ghost:hover {
  background: #ffe3d4;
}
.btn-outline {
  background: #fff;
  color: var(--ink-2);
  border: 1px solid var(--line);
}
.btn-outline:hover {
  border-color: var(--brand);
  color: var(--brand);
}
.btn-block {
  width: 100%;
}
.btn-sm {
  padding: 6px 12px;
  font-size: 13px;
}

.input,
.textarea,
select.input {
